// ============================================================
// Processa as respostas da Data Export API do Microsoft Clarity
// e calcula métricas derivadas de CRO/UX (fricção + engajamento)
// ============================================================
const cfg = $('Config').first().json;

const num = (v) => {
  if (v === null || v === undefined) return 0;
  const n = parseFloat(String(v).replace(',', '.'));
  return isNaN(n) ? 0 : n;
};

// Lê a saída de um nó HTTP do Clarity de forma tolerante a falhas
function getMetrics(nodeName) {
  try {
    const items = $(nodeName).all().map(i => i.json);
    if (!items.length) return [];
    if (items.length === 1 && Array.isArray(items[0])) return items[0];
    if (items.length === 1 && Array.isArray(items[0].body)) return items[0].body;
    return items.filter(m => m && m.metricName);
  } catch (e) { return []; }
}

// Métricas de fricção do Clarity + pesos do Score de Frustração
const FRICTION_METRICS = {
  RageClickCount:   { key: 'rageClicks',      weight: 0.35, label: 'Rage clicks' },
  DeadClickCount:   { key: 'deadClicks',      weight: 0.20, label: 'Dead clicks' },
  QuickbackClick:   { key: 'quickbacks',      weight: 0.15, label: 'Quickbacks' },
  ExcessiveScroll:  { key: 'excessiveScroll', weight: 0.10, label: 'Scroll excessivo' },
  ErrorClickCount:  { key: 'errorClicks',     weight: 0.10, label: 'Error clicks' },
  ScriptErrorCount: { key: 'scriptErrors',    weight: 0.10, label: 'Erros de script' }
};

// Agrupa as métricas por valor de dimensão (URL, Device, Source...)
function buildRows(metrics, dimKeys) {
  const rows = {};
  const rowOf = (entry) => {
    const dim = dimKeys
      .map(k => entry[k] ?? entry[k.toLowerCase()] ?? entry[k.charAt(0).toLowerCase() + k.slice(1)])
      .filter(v => v !== undefined && v !== null && v !== '')
      .join(' · ') || 'Geral';
    if (!rows[dim]) rows[dim] = {
      dimension: dim, sessions: 0, botSessions: 0, users: 0,
      pagesPerSession: null, scrollDepth: null,
      totalTimeSec: 0, activeTimeSec: 0, friction: {}, frictionScore: 0
    };
    return rows[dim];
  };
  for (const m of metrics) {
    const info = Array.isArray(m.information) ? m.information : [];
    for (const e of info) {
      const r = rowOf(e);
      switch (m.metricName) {
        case 'Traffic':
          r.sessions    += num(e.totalSessionCount);
          r.botSessions += num(e.totalBotSessionCount);
          r.users       += num(e.distinctUserCount);
          r.pagesPerSession = num(e.PagesPerSessionPercentage ?? e.pagesPerSessionPercentage);
          break;
        case 'ScrollDepth':
          r.scrollDepth = num(e.averageScrollDepth);
          break;
        case 'EngagementTime':
          r.totalTimeSec  += num(e.totalTime);
          r.activeTimeSec += num(e.activeTime);
          break;
        default:
          if (FRICTION_METRICS[m.metricName]) {
            const f = FRICTION_METRICS[m.metricName];
            r.friction[f.key] = {
              sessions: num(e.sessionsCount),
              pct:      num(e.sessionsWithMetricPercentage),
              total:    num(e.subTotal),
              pagesViews: num(e.pagesViews ?? e.pagesVisited)
            };
          }
      }
    }
  }
  // Score de Frustração por linha (0–100): média ponderada dos % de sessões com fricção
  for (const r of Object.values(rows)) {
    let score = 0;
    for (const f of Object.values(FRICTION_METRICS)) {
      score += f.weight * (r.friction[f.key]?.pct ?? 0);
    }
    r.frictionScore = Math.round(Math.min(100, score) * 10) / 10;
  }
  return Object.values(rows).sort((a, b) => b.frictionScore - a.frictionScore || b.sessions - a.sessions);
}

const byUrl    = buildRows(getMetrics('Clarity – Por URL'), ['URL', 'Url']);
const byDevice = buildRows(getMetrics('Clarity – Por Dispositivo'), ['Device']);
const bySource = buildRows(getMetrics('Clarity – Origem de Tráfego'), ['Source', 'Medium', 'Campaign']);
const byTech   = buildRows(getMetrics('Clarity – Navegador e SO'), ['Browser', 'OS']);

// Visão geral agregada (ponderada por sessões) a partir do corte por URL
function aggregate(rows) {
  const t = { sessions: 0, botSessions: 0, users: 0, activeTime: 0, totalTime: 0 };
  let scrollW = 0, scrollS = 0;
  const fric = {};
  for (const r of rows) {
    t.sessions += r.sessions; t.botSessions += r.botSessions; t.users += r.users;
    t.activeTime += r.activeTimeSec; t.totalTime += r.totalTimeSec;
    if (r.scrollDepth !== null && r.sessions > 0) { scrollW += r.scrollDepth * r.sessions; scrollS += r.sessions; }
    for (const f of Object.values(FRICTION_METRICS)) {
      const fr = r.friction[f.key];
      if (fr) {
        fric[f.key] = fric[f.key] || { sessions: 0, total: 0 };
        fric[f.key].sessions += fr.sessions;
        fric[f.key].total    += fr.total;
      }
    }
  }
  const pctOf = k => t.sessions ? Math.round((fric[k]?.sessions ?? 0) / t.sessions * 1000) / 10 : 0;
  let score = 0;
  for (const f of Object.values(FRICTION_METRICS)) score += f.weight * pctOf(f.key);
  return {
    sessions: t.sessions,
    botSessions: t.botSessions,
    botPct: (t.sessions + t.botSessions) ? Math.round(t.botSessions / (t.sessions + t.botSessions) * 1000) / 10 : 0,
    users: t.users,
    avgScrollDepth: scrollS ? Math.round(scrollW / scrollS * 10) / 10 : null,
    avgActiveTimeSec: t.sessions ? Math.round(t.activeTime / t.sessions) : null,
    avgTotalTimeSec:  t.sessions ? Math.round(t.totalTime / t.sessions) : null,
    frictionRates: Object.fromEntries(Object.values(FRICTION_METRICS).map(f =>
      [f.key, { label: f.label, pctSessions: pctOf(f.key), totalOcorrencias: fric[f.key]?.total ?? 0 }])),
    frustrationScore: Math.round(Math.min(100, score) * 10) / 10
  };
}
const overview = aggregate(byUrl);

// Alertas: páginas com fricção acima do threshold e tráfego relevante
const minSessions = num(cfg.minSessionsForAlert) || 20;
const threshold   = num(cfg.alertFrustrationThreshold) || 15;
const alerts = byUrl
  .filter(r => r.sessions >= minSessions && r.frictionScore >= threshold)
  .slice(0, 10)
  .map(r => ({ url: r.dimension, sessions: r.sessions, frictionScore: r.frictionScore }));

const apiStatus = {
  porUrl: byUrl.length, porDispositivo: byDevice.length,
  origemTrafego: bySource.length, navegadorSo: byTech.length
};

const today = new Date().toISOString().slice(0, 10);
return [{ json: {
  generatedAt: new Date().toISOString(),
  snapshotDate: today,
  projectName: cfg.projectName || 'Meu Projeto',
  periodDays: num(cfg.numOfDays) || 3,
  overview,
  byUrl: byUrl.slice(0, 15),
  byDevice,
  bySource: bySource.slice(0, 12),
  byTech: byTech.slice(0, 12),
  alerts,
  apiStatus
}}];

// ============================================================
// Compara o snapshot atual com o snapshot anterior salvo na
// Data Table `clarity_snapshots` e calcula variações (%)
// ============================================================
const current = $('Processar Métricas Clarity').first().json;

const prevRows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.snapshotDate && r.snapshotDate < current.snapshotDate)
  .sort((a, b) => String(b.snapshotDate).localeCompare(String(a.snapshotDate)));

let prev = null;
if (prevRows[0]?.metrics) {
  try {
    prev = typeof prevRows[0].metrics === 'string'
      ? JSON.parse(prevRows[0].metrics)
      : prevRows[0].metrics;
  } catch (e) { prev = null; }
}

// variação percentual arredondada (null se não comparável)
function delta(cur, old) {
  if (cur === null || cur === undefined || old === null || old === undefined || old === 0) return null;
  return Math.round(((cur - old) / old) * 1000) / 10;
}

let trends = null;
if (prev?.overview) {
  const c = current.overview, p = prev.overview;
  trends = {
    comparadoCom: prevRows[0].snapshotDate,
    sessionsPct:         delta(c.sessions, p.sessions),
    usersPct:            delta(c.users, p.users),
    frustrationScorePct: delta(c.frustrationScore, p.frustrationScore),
    scrollDepthPct:      delta(c.avgScrollDepth, p.avgScrollDepth),
    rageClicksPct:       delta(c.frictionRates?.rageClicks?.pctSessions, p.frictionRates?.rageClicks?.pctSessions),
    deadClicksPct:       delta(c.frictionRates?.deadClicks?.pctSessions, p.frictionRates?.deadClicks?.pctSessions),
    quickbacksPct:       delta(c.frictionRates?.quickbacks?.pctSessions, p.frictionRates?.quickbacks?.pctSessions)
  };
}

return [{ json: { ...current, trends } }];

