// ============================================================
// Extrai o JSON da análise da IA (de forma robusta) e prepara
// o snapshot para salvar na Data Table `clarity_snapshots`
// ============================================================
const raw = $input.first().json;
let text = raw.text ?? raw.output ?? raw.response ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

let analysis = null;
try { analysis = JSON.parse(text); } catch (e) {
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) { try { analysis = JSON.parse(fence[1]); } catch (e2) {} }
  if (!analysis) {
    const m = text.match(/\{[\s\S]*\}/);
    if (m) { try { analysis = JSON.parse(m[0]); } catch (e3) {} }
  }
}
if (!analysis) analysis = {
  resumo_executivo: { nota_geral: null, nivel_urgencia: 'media', sintese: text.slice(0, 1200) || 'Análise indisponível nesta execução.' },
  diagnostico: [], quick_wins: [], investigar_no_clarity: []
};

const data = $('Comparar Tendências').first().json;

return [{ json: {
  snapshotDate: data.snapshotDate,
  projectName: data.projectName,
  frustrationScore: data.overview?.frustrationScore ?? 0,
  analysis,
  metrics: {
    generatedAt: data.generatedAt, snapshotDate: data.snapshotDate, periodDays: data.periodDays,
    overview: data.overview, byUrl: data.byUrl, byDevice: data.byDevice, bySource: data.bySource,
    byTech: data.byTech, alerts: data.alerts, apiStatus: data.apiStatus, trends: data.trends
  }
}}];

// ============================================================
// Renderiza o dashboard CRO/UX (padrão visual Cadastra) com
// seletor de data a partir dos snapshots da Data Table
// ============================================================
const q = $('GET – Relatório CRO').first().json.query ?? {};
const rowsRaw = $input.all().map(i => i.json).filter(r => r && r.snapshotDate && r.metrics);
rowsRaw.sort((a, b) => String(b.snapshotDate).localeCompare(String(a.snapshotDate)));

const dates = [...new Set(rowsRaw.map(r => String(r.snapshotDate)))];
const selDate = (q.date && dates.includes(String(q.date))) ? String(q.date) : dates[0];
const row = rowsRaw.find(r => String(r.snapshotDate) === selDate);

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parse = v => { try { return typeof v === 'string' ? JSON.parse(v) : v; } catch (e) { return null; } };
const fmt  = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR');
const pct  = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR') + '%';
const mmss = s => (s === null || s === undefined) ? '—' : Math.floor(s / 60) + 'm ' + Math.round(s % 60) + 's';

