`;

function scoreCls(v, invert) {
  if (v === null || v === undefined) return 'mid';
  if (invert) return v >= 25 ? 'lo' : v >= 8 ? 'mid' : 'hi';
  return v >= 70 ? 'hi' : v >= 40 ? 'mid' : 'lo';
}
function trendArrow(v, invert) {
  if (v === null || v === undefined) return '';
  const good = invert ? v < 0 : v > 0;
  const color = v === 0 ? 'var(--gray-light)' : good ? 'var(--green)' : 'var(--red)';
  const arrow = v > 0 ? '▲' : v < 0 ? '▼' : '＝';
  return `<span class="kpi-trend" style="color:${color}">${arrow} ${Math.abs(v).toLocaleString('pt-BR')}% vs anterior</span>`;
}
function sevTag(sev) {
  const s = String(sev || 'media').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const map = { critica: 'critical', alta: 'serious', media: 'moderate', baixa: 'minor' };
  return `<span class="impact-tag ${map[s] || 'moderate'}">${esc(sev)}</span>`;
}
function sevItemCls(sev) {
  const s = String(sev || 'media').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  return (s === 'critica' || s === 'alta') ? 'fail' : s === 'media' ? 'warning' : 'pass';
}
function urgBadge(u) {
  const s = String(u || 'media').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
  const cls = (s === 'critica' || s === 'alta') ? 'poor' : s === 'media' ? 'fair' : 'good';
  return `<span class="geo-badge ${cls}">urgência ${esc(u || 'média')}</span>`;
}
function section(icon, title, bodyHtml, open) {
  if (!bodyHtml) return '';
  return `<div class="section">
    <div class="section-head" onclick="tg(this)"><div class="section-title">${icon} ${esc(title)}</div><span class="chev">${open ? '▾' : '▸'}</span></div>
    <div class="section-body${open ? '' : ' hidden'}">${bodyHtml}</div>
  </div>`;
}
function frictionTable(title, rows) {
  if (!rows || !rows.length) return '';
  const tr = rows.map(r => {
    const f = r.friction || {};
    const p = k => f[k]?.pct !== undefined ? pct(f[k].pct) : '—';
    const sc = r.frictionScore >= 25 ? 'var(--red)' : r.frictionScore >= 15 ? '#ea580c' : r.frictionScore >= 8 ? 'var(--yellow)' : 'var(--green)';
    return `<tr>
      <td>${esc(r.dimension)}</td>
      <td class="r">${fmt(r.sessions)}</td>
      <td class="c"><span class="score-pill" style="color:${sc}">${fmt(r.frictionScore)}</span></td>
      <td class="c">${p('rageClicks')}</td>
      <td class="c">${p('deadClicks')}</td>
      <td class="c">${p('quickbacks')}</td>
      <td class="c">${r.scrollDepth !== null && r.scrollDepth !== undefined ? pct(r.scrollDepth) : '—'}</td>
    </tr>`;
  }).join('');
  return `<div class="tbl-title">${esc(title)}</div><div class="tbl-wrap"><table class="tbl">
    <tr><th>Dimensão</th><th class="r">Sessões</th><th class="c">Score Fricção</th><th class="c">Rage %</th><th class="c">Dead %</th><th class="c">Quickback %</th><th class="c">Scroll médio</th></tr>
    ${tr}</table></div>`;
}

