  </select></div>`;

const kpi = (lbl, val, trend) => `<div class="kpi"><div class="kpi-val">${val}</div><div class="kpi-lbl">${esc(lbl)}</div>${trend || ''}</div>`;
const fsCls = scoreCls(ov.frustrationScore, true);
const fsColor = fsCls === 'hi' ? 'var(--green)' : fsCls === 'mid' ? 'var(--yellow)' : 'var(--red)';

const alertsHtml = (data.alerts || []).length ? `<div class="infra-alert">
  <div class="infra-alert-head">🚨 ${data.alerts.length} página(s) acima do limite de fricção</div>
  <ul>${data.alerts.map(a => `<li>${esc(a.url)} — score <b>${fmt(a.frictionScore)}</b> (${fmt(a.sessions)} sessões)</li>`).join('')}</ul>
</div>` : '';

const overviewCard = `<div class="card">
  <div class="card-title">📊 Visão Geral</div>
  <div class="card-sub">${esc(data.projectName)} · últimos ${esc(data.periodDays)} dia(s) · gerado em ${new Date(data.generatedAt).toLocaleString('pt-BR')}${t.comparadoCom ? ' · comparado com ' + esc(t.comparadoCom) : ''}</div>
  <div class="kpi-grid">
    ${kpi('Sessões', fmt(ov.sessions), trendArrow(t.sessionsPct, false))}
    ${kpi('Usuários únicos', fmt(ov.users), trendArrow(t.usersPct, false))}
    ${kpi('Score Frustração', `<span style="color:${fsColor}">${fmt(ov.frustrationScore)}</span>`, trendArrow(t.frustrationScorePct, true))}
    ${kpi('Scroll médio', pct(ov.avgScrollDepth), trendArrow(t.scrollDepthPct, false))}
    ${kpi('Tempo ativo/sessão', mmss(ov.avgActiveTimeSec))}
    ${kpi('Rage clicks', pct(fr.rageClicks?.pctSessions), trendArrow(t.rageClicksPct, true))}
    ${kpi('Dead clicks', pct(fr.deadClicks?.pctSessions), trendArrow(t.deadClicksPct, true))}
    ${kpi('Tráfego bot', pct(ov.botPct))}
  </div>
  <div class="sev-legend">Cortes coletados — URLs: ${data.apiStatus?.porUrl ?? 0} · Dispositivos: ${data.apiStatus?.porDispositivo ?? 0} · Origens: ${data.apiStatus?.origemTrafego ?? 0} · Navegador/SO: ${data.apiStatus?.navegadorSo ?? 0}</div>
  ${alertsHtml}
</div>`;

const resumoHtml = `
  <div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:12px">
